  {
    "id": "H1_seasonal_offset",
    "params": {
      "level": "temp_c",
      "slope": "slope",
      "offset": "delta_c",
      "m_start": "month_n"
    },
    "expr": "where(month() >= m_start, level + offset, level) + slope * T_out",
    "targets": "mean_by_month (negative in spring, positive in autumn)",
    "mechanism": "Calendar-based seasonal changeover: controller adds a fixed offset to the heating curve after a certain month, raising supply in autumn/winter and lowering it in spring/summer.",
    "refute": "If the fitted offset is near zero or the month threshold is outside the heating season, or if held-out RMSE does not improve over S1."
  },
  {
    "id": "H2_morning_boost",
    "params": {
      "level": "temp_c",
      "slope": "slope",
      "boost": "delta_c",
      "n_start": "clock_h",
      "n_end": "clock_h"
    },
    "expr": "where((hour_of_day() >= n_start) & (hour_of_day() < n_end), level + boost + slope * T_out, level + slope * T_out)",
    "targets": "mean_by_local_hour (positive residual in morning hours)",
    "mechanism": "Morning warm-up boost: controller raises supply temperature during a morning window to recover from night setback or preheat the building.",
    "refute": "If the fitted window does not overlap the positive residual hours, or if the boost is negative, or if held-out RMSE does not improve."
  },
  {
    "id": "H3_weather_pi",
    "params": {
      "level": "temp_c",
      "slope": "slope",
      "kp": "gain",
      "sp": "temp_c",
      "ti": "hours"
    },
    "expr": "level + slope * T_out + kp * (sp - T_room) + integral(sp - T_room, ti)",
    "targets": "seasonal drift and room temperature feedback (S6 improvement)",
    "mechanism": "Weather-compensated PI control: outdoor reset plus proportional and integral room temperature feedback to trim supply based on persistent room error.",
    "refute": "If the integral term winds up or the fitted kp/ti are at bounds, or if held-out RMSE does not beat S6."
