  {
    "id": "H1",
    "params": {
      "base": "temp_c",
      "slope": "slope",
      "night_drop": "delta_c",
      "morning_boost": "delta_c",
      "boost_end": "clock_h"
    },
    "expr": "where((hour_of_day() < boost_end) & (hour_of_day() >= boost_end - boost_end), base + slope * T_out + morning_boost, base + slope * T_out - night_drop)",
    "targets": "positive residual at hour 14 and negative residual at hours 2-4; diurnal shape not captured by S1",
    "mechanism": "night setback with a morning recovery boost: controller lowers supply overnight and raises it during an early-morning warm-up window, producing a diurnal residual pattern",
    "refute": "if fitted boost_end collapses to a single hour or night_drop/boost go to zero, the diurnal residual is not a setback schedule"
  },
  {
    "id": "H2",
    "params": {
      "base": "temp_c",
      "slope": "slope",
      "gain": "gain",
      "tc": "hours"
    },
    "expr": "base + slope * T_out + gain * ema(T_out - T_room, tc)",
    "targets": "corr_with_outdoor = -0.23; residual not fully explained by instantaneous T_out",
    "mechanism": "weather-compensated reset with a filtered load signal: controller tracks a slow EMA of the outdoor-room temperature difference, adding heat when the building has been losing heat persistently",
    "refute": "if the EMA time constant fits to near zero or the gain is insignificant, the residual is not a filtered-load effect"
  },
  {
    "id": "H3",
    "params": {
      "base": "temp_c",
      "slope": "slope",
      "wknd_offset": "delta_c"
    },
    "expr": "where((weekday() >= weekday()) & (weekday() <= weekday()), base + slope * T_out + wknd_offset, base + slope * T_out)",
    "targets": "weekend_minus_weekday = 0.08",
    "mechanism": "occupancy-based schedule: controller uses a different supply-temperature curve on weekends than weekdays, e.goiser setpoint or reduced internal-gain compensation",
    "refute": "if wknd_offset fits to zero or the weekend/weekday split does not reduce the residual, occupancy scheduling is not the cause"
