      "params": {"base": "temp_c", "slope": "slope", "mx": "temp_c"},
      "expr": "min(base + slope * T_out, mx)",
      "mechanism": "weather curve with an upper cap on supply water temperature",
      "refute": "the fitted cap lies above every supply value the curve reaches, so it never binds"
    },
    {
      "target": "L1",
